var closedRing = GameObject.Find("Note_Ring_Closed");
var openedRing = GameObject.Find("Note_Ring_Opened");
if (closedRing != null) {
    var mr = closedRing.GetComponent<MeshRenderer>();
    if (mr != null) {
        var mat = mr.sharedMaterial;
        if (!UnityEditor.AssetDatabase.Contains(mat)) {
            UnityEditor.AssetDatabase.CreateAsset(mat, "Assets/Materials/SolidNeon_Cyan.mat");
        }
    }
}
if (openedRing != null) {
    var mr = openedRing.GetComponent<MeshRenderer>();
    if (mr != null) {
        var mat = mr.sharedMaterial;
        if (!UnityEditor.AssetDatabase.Contains(mat)) {
            UnityEditor.AssetDatabase.CreateAsset(mat, "Assets/Materials/SolidNeon_Magenta.mat");
        }
    }
}
UnityEditor.AssetDatabase.SaveAssets();
